[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #FAFAFA;
  --color-surface: #FFFFFF;
  --color-text: #171717;
  --color-text-secondary: #525252;
  --color-text-tertiary: #737373;
  --color-accent: #0072F5;
  --color-accent-hover: #0060D0;
  --color-border: #E5E5E5;
  --color-border-light: #F0F0F0;
  --color-pill-bg: #F5F5F5;
  --color-pill-active-bg: #171717;
  --color-pill-active-text: #FFFFFF;
  --color-footer-bg: #FAFAFA;
  --color-footer-border: #E5E5E5;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Fira Mono', 'Roboto Mono', monospace;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
  --transition-fast: 150ms ease;
  --transition-smooth: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --container-max: 1280px;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }

.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 32px;
}

/* ── Header ──────────────────────────────────── */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header__inner {
  display: flex;
  align-items: center;
  height: 56px;
  gap: 8px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.05rem;
  margin-right: 16px;
  flex-shrink: 0;
}

.header__logo-icon {
  width: 28px;
  height: 28px;
  background: var(--color-text);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 800;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  height: 100%;
}

.header__nav-item {
  position: relative;
  height: 100%;
  display: flex;
  align-items: center;
}

.header__nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.header__nav-link:hover { color: var(--color-text); background: var(--color-pill-bg); }

.header__nav-chevron {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.header__nav-item.open .header__nav-chevron { transform: rotate(180deg); }
.header__nav-item.open > .header__nav-link { color: var(--color-text); }

.header__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.header__btn {
  padding: 6px 16px;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.header__btn--ghost {
  color: var(--color-text-secondary);
}

.header__btn--ghost:hover {
  background: var(--color-pill-bg);
  color: var(--color-text);
}

.header__btn--primary {
  background: var(--color-text);
  color: #fff;
}

.header__btn--primary:hover { background: #333; }

.header__btn--outline {
  border: 1px solid var(--color-border);
  color: var(--color-text);
}

.header__btn--outline:hover { border-color: #999; }

/* ── Mega Menu ───────────────────────────────── */
.megamenu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 28px 32px;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-smooth), transform var(--transition-smooth), visibility var(--transition-smooth);
  min-width: 480px;
  z-index: 200;
}

.header__nav-item.open .megamenu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(4px);
}

.megamenu__content { display: flex; gap: 40px; }

.megamenu__section { flex: 1; }

.megamenu__section-title {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-tertiary);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--color-border-light);
}

.megamenu__list { display: flex; flex-direction: column; gap: 2px; }

.megamenu__link {
  display: flex;
  flex-direction: column;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
  font-size: 0.8125rem;
}

.megamenu__link:hover { background: var(--color-pill-bg); }

.megamenu__link-title {
  font-weight: 500;
  color: var(--color-text);
  line-height: 1.4;
}

.megamenu__link-desc {
  font-size: 0.75rem;
  color: var(--color-text-tertiary);
  line-height: 1.3;
  margin-top: 1px;
}

/* Resources dropdown (simpler) */
.dropdown {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 12px;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-smooth), transform var(--transition-smooth), visibility var(--transition-smooth);
  min-width: 200px;
  z-index: 200;
}

.header__nav-item.open .dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(4px);
}

.dropdown__link {
  display: block;
  padding: 8px 14px;
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast), color var(--transition-fast);
  font-weight: 500;
}

.dropdown__link:hover { background: var(--color-pill-bg); color: var(--color-text); }

/* ── Filters Bar ─────────────────────────────── */
.filters-bar {
  padding: 32px 0 20px;
}

.filters-bar__inner {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.filters-bar__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  flex: 1;
  min-width: 0;
}

.filters-bar__pill {
  padding: 7px 16px;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: var(--radius-full);
  background: var(--color-pill-bg);
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  white-space: nowrap;
  border: 1px solid transparent;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.filters-bar__pill:hover {
  background: #E8E8E8;
  color: var(--color-text);
}

.filters-bar__pill--active {
  background: var(--color-pill-active-bg);
  color: var(--color-pill-active-text);
}

.filters-bar__pill--active:hover {
  background: #333;
  color: #fff;
}

.filters-bar__search {
  position: relative;
  flex-shrink: 0;
  width: 240px;
}

.filters-bar__search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--color-text-tertiary);
  pointer-events: none;
}

.filters-bar__search input {
  width: 100%;
  padding: 9px 14px 9px 40px;
  font-size: 0.8125rem;
  font-family: var(--font-sans);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  background: var(--color-surface);
  color: var(--color-text);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  min-height: 44px;
}

.filters-bar__search input::placeholder { color: var(--color-text-tertiary); }

.filters-bar__search input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0,114,245,0.1);
}

/* ── Featured Articles ────────────────────────── */
.featured {
  padding: 0 0 48px;
}

.section-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-tertiary);
  margin-bottom: 16px;
}

.featured__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.featured__card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-smooth), box-shadow var(--transition-smooth);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.featured__card:hover {
  border-color: #CCC;
  box-shadow: var(--shadow-md);
}

.featured__card:first-child {
  background: var(--color-text);
  color: #fff;
  border-color: var(--color-text);
}

.featured__card:first-child:hover {
  border-color: #333;
}

.featured__card:first-child .featured__date,
.featured__card:first-child .featured__title,
.featured__card:first-child .featured__excerpt,
.featured__card:first-child .featured__author {
  color: inherit;
}

.featured__card:first-child .featured__date { color: rgba(255,255,255,0.65); }
.featured__card:first-child .featured__title { color: #fff; }
.featured__card:first-child .featured__excerpt { color: rgba(255,255,255,0.75); }
.featured__card:first-child .featured__author { color: rgba(255,255,255,0.8); }

/* Stats inside first featured card */
.featured__stats {
  margin-top: auto;
  padding-top: 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  border-top: 1px solid rgba(255,255,255,0.15);
}

.featured__stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: #fff;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.featured__stat-label {
  font-size: 0.6875rem;
  color: rgba(255,255,255,0.6);
  margin-top: 4px;
  line-height: 1.3;
}

.featured__date {
  font-size: 0.75rem;
  color: var(--color-text-tertiary);
  margin-bottom: 12px;
  font-weight: 500;
}

.featured__title {
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.featured__excerpt {
  font-size: 0.84375rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  flex: 1;
}

.featured__author {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
}

.featured__author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  flex-shrink: 0;
}

.featured__card:first-child .featured__author-avatar {
  background: rgba(255,255,255,0.2);
}

/* ── Latest News ─────────────────────────────── */
.latest {
  padding: 0 0 24px;
}

.latest__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.post-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 22px 24px;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-smooth), box-shadow var(--transition-smooth);
  cursor: pointer;
}

.post-card:hover {
  border-color: #CCC;
  box-shadow: var(--shadow-sm);
}

.post-card__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.post-card__category {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-accent);
  padding: 3px 10px;
  background: rgba(0,114,245,0.06);
  border-radius: var(--radius-full);
}

.post-card__date {
  font-size: 0.75rem;
  color: var(--color-text-tertiary);
  font-weight: 500;
}

.post-card__title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.post-card__excerpt {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  line-height: 1.55;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card__author {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 14px;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--color-text-tertiary);
}

.post-card__author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* ── Show More ───────────────────────────────── */
.show-more-wrap {
  text-align: center;
  padding: 16px 0 40px;
}

.show-more-btn {
  padding: 10px 32px;
  font-size: 0.84375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  color: var(--color-text);
  min-height: 44px;
  transition: all var(--transition-fast);
}

.show-more-btn:hover {
  border-color: #999;
  background: var(--color-pill-bg);
}

.show-more-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ── No Results ──────────────────────────────── */
.no-results {
  display: none;
  text-align: center;
  padding: 64px 24px;
  grid-column: 1 / -1;
}

.no-results--visible { display: block; }

.no-results__icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  color: var(--color-text-tertiary);
  opacity: 0.4;
}

.no-results__text {
  font-size: 0.9375rem;
  color: var(--color-text-tertiary);
  font-weight: 500;
}

/* ── CTA Banner ──────────────────────────────── */
.cta-banner {
  background: var(--color-text);
  color: #fff;
  margin: 0 0 0;
}

.cta-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding: 60px 0;
}

.cta-banner__content { flex: 1; }

.cta-banner__headline {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.cta-banner__subheadline {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.65);
}

.cta-banner__subheadline strong { color: #fff; }

.cta-banner__actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.cta-btn {
  padding: 12px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}

.cta-btn--primary {
  background: #fff;
  color: var(--color-text);
}

.cta-btn--primary:hover { background: #E8E8E8; }

.cta-btn--secondary {
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.3);
}

.cta-btn--secondary:hover { background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.5); }

.cta-banner__enterprise {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
  width: 100%;
}

.cta-banner__enterprise p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.65);
}

.cta-banner__enterprise .cta-btn {
  margin-top: 12px;
}

/* ── Footer ──────────────────────────────────── */
.footer {
  background: #F5F5F5;
  border-top: 1px solid var(--color-border);
  padding: 64px 0 32px;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px 24px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--color-border);
}

.footer__col { min-width: 0; }

.footer__col-title {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer__link {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
  line-height: 1.4;
}

.footer__link:hover { color: var(--color-text); }

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 28px;
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
  flex-wrap: wrap;
  gap: 16px;
}

.footer__status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer__status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #16A34A;
  flex-shrink: 0;
}

.footer__copyright { color: var(--color-text-tertiary); }

/* ── Responsive ──────────────────────────────── */
@media (max-width: 1024px) {
  .header__nav-link { padding: 6px 8px; font-size: 0.8125rem; }
  .featured__grid, .latest__grid { grid-template-columns: repeat(2, 1fr); }
  .featured__stats { grid-template-columns: repeat(3, 1fr); }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .filters-bar__search { width: 200px; }
}

@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .header__nav { display: none; }
  .header__actions .header__btn--ghost { display: none; }
  .featured__grid, .latest__grid { grid-template-columns: 1fr; }
  .featured__stats { grid-template-columns: repeat(3, 1fr); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .filters-bar__inner { flex-direction: column; align-items: stretch; }
  .filters-bar__search { width: 100%; }
  .filters-bar__pills { overflow-x: auto; flex-wrap: nowrap; padding-bottom: 4px; }
  .cta-banner__inner { flex-direction: column; text-align: center; padding: 48px 0; }
  .cta-banner__headline { font-size: 1.25rem; }
}

@media (max-width: 480px) {
  .featured__stats { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}

/* ── Animations ──────────────────────────────── */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.post-card--animate {
  animation: fadeIn 0.35s ease forwards;
}

/* ── Mobile menu toggle ──────────────────────── */
.header__hamburger {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  margin-left: auto;
  min-height: 44px;
  min-width: 44px;
  align-items: center;
  justify-content: center;
}

.header__hamburger span {
  width: 18px;
  height: 2px;
  background: var(--color-text);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

@media (max-width: 768px) {
  .header__hamburger { display: flex; }
}

/* Hidden extra posts */
.post-card--hidden { display: none; }
</style>
</head>
