      var catMatch = activeCategory === 'all' || post.category === activeCategory;
      if (!catMatch) return false;
      if (!searchQuery.trim()) return true;
      var q = searchQuery.toLowerCase().trim();
      return post.title.toLowerCase().indexOf(q) !== -1 ||
             post.excerpt.toLowerCase().indexOf(q) !== -1 ||
             post.author.toLowerCase().indexOf(q) !== -1 ||
             post.categoryLabel.toLowerCase().indexOf(q) !== -1;
    });
  }

  // ── Render grid ────────────────────────────────
  function renderGrid(animateNew) {
    var grid = document.getElementById('posts-grid');
    var noResults = document.getElementById('no-results');
    var showMoreWrap = document.getElementById('show-more-wrap');
    var filtered = getFilteredPosts();

    // Clear grid
    grid.innerHTML = '';

    if (filtered.length === 0) {
      noResults.classList.add('no-results--visible');
      showMoreWrap.style.display = 'none';
      return;
    }

    noResults.classList.remove('no-results--visible');

    var toShow = filtered.slice(0, visibleCount);
    var remaining = filtered.length - toShow.length;

    toShow.forEach(function(post, i) {
      var animate = animateNew && i >= visibleCount - (visibleCount > POSTS_PER_PAGE ? (visibleCount - Math.max(0, visibleCount - POSTS_PER_PAGE)) : POSTS_PER_PAGE);
      grid.appendChild(createPostCard(post, false));
    });

    if (remaining > 0) {
      showMoreWrap.style.display = 'block';
      var btn = document.getElementById('show-more-btn');
      btn.disabled = false;
      btn.textContent = 'Show more posts';
    } else {
      showMoreWrap.style.display = 'none';
    }
  }

  // ── Category filtering ─────────────────────────
  var pills = document.querySelectorAll('.filters-bar__pill');
  pills.forEach(function(pill) {
    pill.addEventListener('click', function() {
      pills.forEach(function(p) {
        p.classList.remove('filters-bar__pill--active');
        p.setAttribute('aria-selected', 'false');
      });
      pill.classList.add('filters-bar__pill--active');
      pill.setAttribute('aria-selected', 'true');
      activeCategory = pill.getAttribute('data-category');
      visibleCount = POSTS_PER_PAGE;
      renderGrid(true);
    });
  });

  // ── Search ─────────────────────────────────────
  var searchInput = document.getElementById('search-input');
  var searchTimeout;
  searchInput.addEventListener('input', function() {
    clearTimeout(searchTimeout);
    searchTimeout = setTimeout(function() {
      searchQuery = searchInput.value;
      visibleCount = POSTS_PER_PAGE;
      renderGrid(true);
    }, 200);
  });

  // ── Show more ──────────────────────────────────
  document.getElementById('show-more-btn').addEventListener('click', function() {
    visibleCount += POSTS_PER_PAGE;
    var filtered = getFilteredPosts();
    if (visibleCount >= filtered.length) {
      visibleCount = filtered.length;
    }
    renderGrid(true);
  });

  // ── Dropdowns ──────────────────────────────────
  var dropdownItems = document.querySelectorAll('[data-dropdown]');
  var openDropdown = null;

  dropdownItems.forEach(function(item) {
    var btn = item.querySelector('.header__nav-link');
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      if (openDropdown === item) {
        closeDropdowns();
      } else {
        closeDropdowns();
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        openDropdown = item;
      }
    });

    item.addEventListener('mouseenter', function() {
      if (openDropdown && openDropdown !== item) {
        closeDropdowns();
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        openDropdown = item;
      }
    });
  });

  function closeDropdowns() {
    dropdownItems.forEach(function(item) {
      item.classList.remove('open');
      var b = item.querySelector('.header__nav-link');
      if (b) b.setAttribute('aria-expanded', 'false');
    });
    openDropdown = null;
  }

  // Close on outside click
  document.addEventListener('click', function(e) {
    if (!e.target.closest('[data-dropdown]')) {
      closeDropdowns();
    }
  });

  // Close on Escape
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeDropdowns();
  });

  // ── Initial render ─────────────────────────────
  renderGrid(false);
})();
</script>

